// CLI parsing mimicking clap v2 behavior.

use std::process::exit;

pub struct ImageOpts {
    pub width: u32,
    pub height: u32,
    pub webify: Option<u32>,
    pub no_color: bool,  // -b flag (applies if given at top level)
    pub yaw: f64,
    pub pitch: f64,
    pub roll: f64,
}

pub enum Command {
    Image {
        inputs: Vec<String>,
        opts: ImageOpts,
    },
    Interactive {
        inputs: Vec<String>,
        no_color: bool,
        yaw: f64,
        pitch: f64,
        roll: f64,
    },
}

pub struct ClapError {
    pub message: String,
    pub usage_line: String,
}

impl ClapError {
    pub fn print(&self) {
        eprintln!("error: {}", self.message);
        eprintln!("");
        eprintln!("USAGE:");
        eprintln!("    {}", self.usage_line);
        eprintln!("");
        eprintln!("For more information try --help");
    }
}

const BIN_NAME: &str = "executable";

const MAIN_USAGE: &str = "executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]";
const IMAGE_USAGE_SHORT: &str = "executable image [FLAGS] [OPTIONS] -w <width>";
const IMAGE_USAGE_FULL: &str = "executable <input filename(s)>... image [FLAGS] [OPTIONS] -w <width>";

fn print_main_help() {
    let text = r#"Sloth 0.1
Mitchell Hynes. <mshynes@mun.ca>
A toy for rendering 3D objects in the command line

USAGE:
    executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]

FLAGS:
    -h, --help       Prints help information
    -b               Flags the rasterizer to render without color
    -V, --version    Prints version information

OPTIONS:
    -x, --yaw <x>      Sets the object's static X rotation (in radians)
    -y, --pitch <y>    Sets the object's static Y rotation (in radians)
    -z, --roll <z>     Sets the object's static Z rotation (in radians)

ARGS:
    <input filename(s)>...    Sets the input file to render

SUBCOMMANDS:
    help     Prints this message or the help of the given subcommand(s)
    image    Generates a colorless terminal output as lines of text"#;
    println!("{}", text);
}

fn print_image_help(long: bool) {
    // For `image --help`, usage line is: executable image [FLAGS]...
    // For `executable help image`, same.
    let usage = if long { IMAGE_USAGE_SHORT } else { IMAGE_USAGE_SHORT };
    let text = format!(r#"executable-image 
Mitchell Hynes <mitchell.hynes@ecumene.xyz>
Generates a colorless terminal output as lines of text

USAGE:
    {}

FLAGS:
        --help       Prints help information
    -b               Flags the rasterizer to render without color
    -V, --version    Prints version information

OPTIONS:
    -j, --webify <frame count>    Generates a portable JS based render of your object for the web
    -h <height>                   Sets the height of the image to generate
    -w <width>                    Sets the width of the image to generate
    -x, --yaw <x>                 Sets the object's static X rotation (in radians)
    -y, --pitch <y>               Sets the object's static Y rotation (in radians)
    -z, --roll <z>                Sets the object's static Z rotation (in radians)"#, usage);
    println!("{}", text);
}

fn print_version() {
    println!("Sloth 0.1");
}

fn print_version_image() {
    println!("executable-image ");
}

fn err_required_input() -> ClapError {
    ClapError {
        message: "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
        usage_line: MAIN_USAGE.to_string(),
    }
}

fn err_required_width(usage: &str) -> ClapError {
    ClapError {
        message: "The following required arguments were not provided:\n    -w <width>".to_string(),
        usage_line: usage.to_string(),
    }
}

fn err_unexpected_arg(arg: &str, usage: &str) -> ClapError {
    ClapError {
        message: format!(
            "Found argument '{}' which wasn't expected, or isn't valid in this context",
            arg
        ),
        usage_line: usage.to_string(),
    }
}

fn parse_float(s: &str) -> Result<f64, ()> {
    s.parse::<f64>().map_err(|_| ())
}

fn parse_uint(s: &str) -> Result<u32, String> {
    s.parse::<u32>().map_err(|_| "ParseIntError { kind: InvalidDigit }".to_string())
}

pub fn parse(args: &[String]) -> Result<Command, ClapError> {
    // Skip argv[0]
    let argv: Vec<&str> = args.iter().skip(1).map(|s| s.as_str()).collect();
    parse_main(&argv)
}

fn is_flag_or_opt(s: &str) -> bool {
    s.starts_with('-') && s != "-" && !(s.len() > 1 && s.chars().nth(1).map_or(false, |c| c.is_ascii_digit()))
}

fn parse_main(argv: &[&str]) -> Result<Command, ClapError> {
    // parse top-level flags/options until we hit a positional (subcommand/input) or end
    let mut i = 0;
    let mut no_color = false;
    let mut yaw: Option<f64> = None;
    let mut pitch: Option<f64> = None;
    let mut roll: Option<f64> = None;
    let mut inputs: Vec<String> = Vec::new();
    let mut saw_subcommand: Option<usize> = None;

    while i < argv.len() {
        let a = argv[i];
        match a {
            "-h" | "--help" => {
                print_main_help();
                exit(0);
            }
            "-V" | "--version" => {
                print_version();
                exit(0);
            }
            "-b" => { no_color = true; i += 1; }
            "-x" | "--yaw" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-x <x>", "--yaw <x>", MAIN_USAGE));
                }
                let v = argv[i+1];
                match parse_float(v) {
                    Ok(f) => { yaw = Some(f); i += 2; }
                    Err(_) => {
                        return Err(err_unexpected_arg(v, &format!("executable <input filename(s)>... --yaw <x>")));
                    }
                }
            }
            "-y" | "--pitch" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-y <y>", "--pitch <y>", MAIN_USAGE));
                }
                let v = argv[i+1];
                match parse_float(v) {
                    Ok(f) => { pitch = Some(f); i += 2; }
                    Err(_) => {
                        return Err(err_unexpected_arg(v, &format!("executable <input filename(s)>... --pitch <y>")));
                    }
                }
            }
            "-z" | "--roll" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-z <z>", "--roll <z>", MAIN_USAGE));
                }
                let v = argv[i+1];
                match parse_float(v) {
                    Ok(f) => { roll = Some(f); i += 2; }
                    Err(_) => {
                        return Err(err_unexpected_arg(v, &format!("executable <input filename(s)>... --roll <z>")));
                    }
                }
            }
            _ if a.starts_with("--") => {
                // Unknown long flag
                return Err(err_unexpected_arg(a, MAIN_USAGE));
            }
            _ if a.starts_with('-') && !a.chars().nth(1).map_or(false, |c| c.is_ascii_digit()) => {
                // Unknown short flag (but -0.5 is a valid number, -5 starts with digit)
                return Err(err_unexpected_arg(a, MAIN_USAGE));
            }
            "help" => {
                // help subcommand: show either main help or image help
                if i + 1 < argv.len() {
                    let next = argv[i+1];
                    if next == "image" {
                        print_image_help(true);
                        exit(0);
                    }
                }
                print_main_help();
                exit(0);
            }
            "image" => {
                saw_subcommand = Some(i);
                break;
            }
            _ => {
                // Positional input filename
                inputs.push(a.to_string());
                i += 1;
            }
        }
    }

    // Check if we have inputs before subcommand
    // In clap v2, if top-level flags are given but no inputs and no subcommand, usage includes those flags
    // We handle the most common cases.

    if let Some(sub_idx) = saw_subcommand {
        // We have `image` subcommand - parse its args
        let image_argv: Vec<&str> = argv[sub_idx+1..].iter().cloned().collect();
        // But inputs might be missing - they come before 'image'
        if inputs.is_empty() {
            // Need to check for -w in image args first before complaining about inputs.
            // Actually clap v2 requires the inputs (positional) to be present even with a subcommand.
            // Based on observation: without inputs and with 'image' subcommand -> asks for -w (because image is a subcommand missing a flag).
            // Wait: running `executable image` gave the -w error. So clap processed 'image' subcommand even without inputs.
            // This means 'image' takes precedence, and errors for image subcommand fire first.
        }
        return parse_image(&image_argv, inputs, no_color, yaw.unwrap_or(0.0), pitch.unwrap_or(0.0), roll.unwrap_or(0.0));
    }

    // No subcommand - interactive mode. Inputs required.
    if inputs.is_empty() {
        // Build usage with appropriate tail
        let mut usage = "executable <input filename(s)>...".to_string();
        if no_color {
            usage = format!("{} -b", usage);
        }
        if yaw.is_some() {
            usage = format!("{} --yaw <x>", usage);
        }
        if pitch.is_some() {
            usage = format!("{} --pitch <y>", usage);
        }
        if roll.is_some() {
            usage = format!("{} --roll <z>", usage);
        }
        if usage == "executable <input filename(s)>..." {
            // No other options set - use normal usage
            return Err(err_required_input());
        } else {
            return Err(ClapError {
                message: "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
                usage_line: usage,
            });
        }
    }

    Ok(Command::Interactive {
        inputs,
        no_color,
        yaw: yaw.unwrap_or(0.0),
        pitch: pitch.unwrap_or(0.0),
        roll: roll.unwrap_or(0.0),
    })
}

fn missing_opt_value(short: &str, long: &str, usage: &str) -> ClapError {
    // This isn't exactly how clap works but for now
    ClapError {
        message: format!(
            "The argument '{}' requires a value but none was supplied",
            long
        ),
        usage_line: usage.to_string(),
    }
}

fn parse_image(
    argv: &[&str],
    inputs: Vec<String>,
    no_color: bool,
    yaw: f64,
    pitch: f64,
    roll: f64,
) -> Result<Command, ClapError> {
    let mut i = 0;
    let mut width: Option<u32> = None;
    let mut height: Option<u32> = None;
    let mut webify: Option<u32> = None;
    let mut sub_yaw = yaw;
    let mut sub_pitch = pitch;
    let mut sub_roll = roll;
    let mut sub_no_color = no_color; // no effect but keep

    while i < argv.len() {
        let a = argv[i];
        match a {
            "--help" => {
                print_image_help(false);
                exit(0);
            }
            "-V" | "--version" => {
                print_version_image();
                exit(0);
            }
            "-b" => { sub_no_color = true; i += 1; }
            "-w" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-w <width>", "-w <width>", IMAGE_USAGE_SHORT));
                }
                let v = argv[i+1];
                match parse_uint(v) {
                    Ok(n) => { width = Some(n); i += 2; }
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        exit(1);
                    }
                }
            }
            "-h" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-h <height>", "-h <height>", IMAGE_USAGE_SHORT));
                }
                let v = argv[i+1];
                match parse_uint(v) {
                    Ok(n) => { height = Some(n); i += 2; }
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        exit(1);
                    }
                }
            }
            "-j" | "--webify" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-j <frame count>", "--webify <frame count>", IMAGE_USAGE_SHORT));
                }
                let v = argv[i+1];
                match parse_uint(v) {
                    Ok(n) => { webify = Some(n); i += 2; }
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        exit(1);
                    }
                }
            }
            "-x" | "--yaw" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-x <x>", "--yaw <x>", IMAGE_USAGE_SHORT));
                }
                let v = argv[i+1];
                match parse_float(v) {
                    Ok(f) => { sub_yaw = f; i += 2; }
                    Err(_) => return Err(err_unexpected_arg(v, IMAGE_USAGE_SHORT)),
                }
            }
            "-y" | "--pitch" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-y <y>", "--pitch <y>", IMAGE_USAGE_SHORT));
                }
                let v = argv[i+1];
                match parse_float(v) {
                    Ok(f) => { sub_pitch = f; i += 2; }
                    Err(_) => return Err(err_unexpected_arg(v, IMAGE_USAGE_SHORT)),
                }
            }
            "-z" | "--roll" => {
                if i + 1 >= argv.len() {
                    return Err(missing_opt_value("-z <z>", "--roll <z>", IMAGE_USAGE_SHORT));
                }
                let v = argv[i+1];
                match parse_float(v) {
                    Ok(f) => { sub_roll = f; i += 2; }
                    Err(_) => return Err(err_unexpected_arg(v, IMAGE_USAGE_SHORT)),
                }
            }
            _ => {
                return Err(err_unexpected_arg(a, IMAGE_USAGE_SHORT));
            }
        }
    }

    let w = match width {
        Some(w) => w,
        None => {
            // Use the appropriate usage based on whether inputs were provided
            let usage = if inputs.is_empty() {
                IMAGE_USAGE_SHORT
            } else {
                IMAGE_USAGE_FULL
            };
            // If -h was also given, usage changes
            if height.is_some() && inputs.is_empty() {
                return Err(err_required_width("executable image -h <height> -w <width>"));
            }
            return Err(err_required_width(usage));
        }
    };

    if inputs.is_empty() {
        return Err(err_required_input());
    }

    let h = height.unwrap_or(w);

    Ok(Command::Image {
        inputs,
        opts: ImageOpts {
            width: w,
            height: h,
            webify,
            no_color: sub_no_color,
            yaw: sub_yaw,
            pitch: sub_pitch,
            roll: sub_roll,
        },
    })
}

pub fn run(cmd: Command) {
    match cmd {
        Command::Image { inputs, opts } => {
            // Split inputs if quoted string has multiple filenames separated by space
            let all_files: Vec<String> = inputs
                .iter()
                .flat_map(|s| s.split_whitespace().map(|x| x.to_string()))
                .collect();
            let models = load_models(&all_files);
            crate::output::render_image(&models, &opts);
        }
        Command::Interactive { inputs, no_color, yaw, pitch, roll } => {
            // Interactive mode requires a TTY; fall back to failing similarly to original.
            let _ = (inputs, no_color, yaw, pitch, roll);
            eprintln!("Error: IoError(Os {{ code: 25, kind: Uncategorized, message: \"Inappropriate ioctl for device\" }})");
            exit(1);
        }
    }
}

fn load_models(files: &[String]) -> Vec<crate::obj::Model> {
    let mut models = Vec::new();
    for f in files {
        match crate::obj::load(f) {
            Ok(m) => models.push(m),
            Err(e) => {
                // Panic like the original
                eprintln!("");
                eprintln!("thread 'main' ({}) panicked at src/inputs.rs:126:39:", std::process::id());
                eprintln!("called `Result::unwrap()` on an `Err` value: \"{}\"", e);
                eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
                exit(101);
            }
        }
    }
    models
}
EOF
