fn parse_uint(s: &str) -> Result<u32, String> {
    s.parse::<u32>().map_err(|_| "ParseIntError { kind: InvalidDigit }".to_string())
}

pub fn parse(args: &[String]) -> Result<Command, ClapError> {
    // Skip argv[0]
    let argv: Vec<&str> = args.iter().skip(1).map(|s| s.as_str()).collect();
