    }

    // No subcommand - interactive mode. Inputs required.
    if inputs.is_empty() {
        // Build usage with appropriate tail
        let mut usage = "executable <input filename(s)>...".to_string();
        if no_color {
            usage = format!("{} -b", usage);
        }
        if yaw.is_some() {
            usage = format!("{} --yaw <x>", usage);
        }
        if pitch.is_some() {
            usage = format!("{} --pitch <y>", usage);
        }
        if roll.is_some() {
            usage = format!("{} --roll <z>", usage);
        }
        if usage == "executable <input filename(s)>..." {
            // No other options set - use normal usage
            return Err(err_required_input());
        } else {
            return Err(ClapError {
                message: "The following required arguments were not provided:\n    <input filename(s)>...".to_string(),
                usage_line: usage,
            });
        }
    }

    Ok(Command::Interactive {
        inputs,
        no_color,
        yaw: yaw.unwrap_or(0.0),
        pitch: pitch.unwrap_or(0.0),
        roll: roll.unwrap_or(0.0),
    })
}

fn missing_opt_value(short: &str, long: &str, usage: &str) -> ClapError {
