// Simple 3D math

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Vec3 { pub x: f64, pub y: f64, pub z: f64 }

impl Vec3 {
    pub fn new(x: f64, y: f64, z: f64) -> Self { Vec3 { x, y, z } }
    pub fn sub(self, o: Vec3) -> Vec3 { Vec3::new(self.x-o.x, self.y-o.y, self.z-o.z) }
    pub fn add(self, o: Vec3) -> Vec3 { Vec3::new(self.x+o.x, self.y+o.y, self.z+o.z) }
    pub fn scale(self, s: f64) -> Vec3 { Vec3::new(self.x*s, self.y*s, self.z*s) }
    pub fn dot(self, o: Vec3) -> f64 { self.x*o.x + self.y*o.y + self.z*o.z }
    pub fn cross(self, o: Vec3) -> Vec3 {
        Vec3::new(
            self.y*o.z - self.z*o.y,
            self.z*o.x - self.x*o.z,
            self.x*o.y - self.y*o.x,
        )
    }
    pub fn len(self) -> f64 { self.dot(self).sqrt() }
    pub fn normalize(self) -> Vec3 {
        let l = self.len();
        if l > 0.0 { self.scale(1.0/l) } else { self }
    }
}

pub fn rotate(v: Vec3, yaw: f64, pitch: f64, roll: f64) -> Vec3 {
    // yaw = x rot, pitch = y rot, roll = z rot
    let cy = yaw.cos(); let sy = yaw.sin();
    let cp = pitch.cos(); let sp = pitch.sin();
    let cr = roll.cos(); let sr = roll.sin();
    // Rotate around X
    let (x1, y1, z1) = (v.x, cy*v.y - sy*v.z, sy*v.y + cy*v.z);
    // Rotate around Y
    let (x2, y2, z2) = (cp*x1 + sp*z1, y1, -sp*x1 + cp*z1);
    // Rotate around Z
    let (x3, y3, z3) = (cr*x2 - sr*y2, sr*x2 + cr*y2, z2);
    Vec3::new(x3, y3, z3)
}
