// Minimal OBJ and MTL parser

use std::fs;
use std::path::Path;
use crate::math::Vec3;

#[derive(Clone, Debug, Default)]
pub struct Material {
    pub name: String,
    pub diffuse: (f64, f64, f64),
}

#[derive(Clone, Debug, Default)]
pub struct Mesh {
    pub vertices: Vec<Vec3>,
    pub normals: Vec<Vec3>,
    /// Each face: vec of (vertex_idx, normal_idx_opt)
    pub faces: Vec<Face>,
    pub material: Option<Material>,
}

#[derive(Clone, Debug, Default)]
pub struct Face {
    pub vs: Vec<usize>,
    pub ns: Vec<Option<usize>>,
}

pub struct Model {
    pub meshes: Vec<Mesh>,
}

pub fn load(path: &str) -> Result<Model, String> {
    let p = Path::new(path);
    // Check extension
    let ext = match p.extension().and_then(|e| e.to_str()) {
        Some(e) => e.to_lowercase(),
        None => return Err(format!(
            "filename: [{}] couldn't load, couldn't determine filename extension. ",
            path
        )),
    };

    if ext == "obj" {
        return load_obj(path);
    } else if ext == "stl" {
        return load_stl(path);
    }
    // Unknown extension
    Err(format!(
        "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed",
        path
    ))
}

fn load_obj(path: &str) -> Result<Model, String> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return Err(format!(
            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed",
            path
        )),
    };
    let dir = Path::new(path).parent().unwrap_or(Path::new("."));

    let mut mtllib: Option<String> = None;
    let mut vertices: Vec<Vec3> = Vec::new();
    let mut normals: Vec<Vec3> = Vec::new();
    let mut meshes: Vec<Mesh> = Vec::new();
    let mut current = Mesh::default();
    let mut materials: Vec<Material> = Vec::new();
    let mut have_current_face = false;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        let mut parts = line.split_whitespace();
        let key = parts.next().unwrap_or("");
        match key {
            "mtllib" => {
                if let Some(name) = parts.next() {
                    mtllib = Some(name.to_string());
                }
            }
            "v" => {
                let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                if nums.len() >= 3 {
                    vertices.push(Vec3::new(nums[0], nums[1], nums[2]));
                }
            }
            "vn" => {
                let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                if nums.len() >= 3 {
                    normals.push(Vec3::new(nums[0], nums[1], nums[2]));
                }
            }
            "usemtl" => {
                // Start new mesh if current has faces
                if have_current_face {
                    meshes.push(std::mem::take(&mut current));
                    have_current_face = false;
                }
                let mat_name = parts.next().unwrap_or("");
                // Must load materials now if not loaded yet
                if materials.is_empty() {
                    if let Some(ref lib) = mtllib {
                        let mtl_path = dir.join(lib);
                        materials = load_mtl(mtl_path.to_str().unwrap_or(""))?;
                    }
                }
                current.material = materials.iter().find(|m| m.name == mat_name).cloned();
                current.vertices = vertices.clone();
                current.normals = normals.clone();
            }
            "f" => {
                let mut face = Face::default();
                for spec in parts {
                    // spec may be "v" or "v/t" or "v/t/n" or "v//n"
                    let mut it = spec.split('/');
                    let v = it.next().unwrap_or("").parse::<i64>().unwrap_or(0);
                    let _t = it.next();
                    let n = it.next().and_then(|s| if s.is_empty() { None } else { s.parse::<i64>().ok() });
                    let vi = resolve_idx(v, vertices.len());
                    let ni = n.map(|nn| resolve_idx(nn, normals.len()));
                    face.vs.push(vi);
                    face.ns.push(ni);
                }
                if face.vs.len() >= 3 {
                    current.faces.push(face);
                    have_current_face = true;
                }
            }
            _ => {}
        }
    }

    if have_current_face {
        if current.vertices.is_empty() {
            current.vertices = vertices.clone();
            current.normals = normals.clone();
        }
        meshes.push(current);
    }

    // Check if materials loading was needed and failed
    if let Some(ref lib) = mtllib {
        if materials.is_empty() {
            // Try loading - if failed, panic-style
            let mtl_path = dir.join(lib);
            if !mtl_path.exists() {
                return Err("Expected to have materials.: OpenFileFailed".to_string());
            }
        }
    }

    Ok(Model { meshes })
}

fn resolve_idx(i: i64, total: usize) -> usize {
    if i < 0 { (total as i64 + i) as usize } else { (i - 1) as usize }
}

fn load_mtl(path: &str) -> Result<Vec<Material>, String> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return Err("Expected to have materials.: OpenFileFailed".to_string()),
    };
    let mut mats: Vec<Material> = Vec::new();
    let mut current: Option<Material> = None;

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        let mut parts = line.split_whitespace();
        let key = parts.next().unwrap_or("");
        match key {
            "newmtl" => {
                if let Some(m) = current.take() {
                    mats.push(m);
                }
                current = Some(Material { name: parts.next().unwrap_or("").to_string(), diffuse: (1.0, 1.0, 1.0) });
            }
            "Kd" => {
                let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                if let Some(m) = current.as_mut() {
                    if nums.len() >= 3 {
                        m.diffuse = (nums[0], nums[1], nums[2]);
                    }
                }
            }
            _ => {}
        }
    }
    if let Some(m) = current.take() { mats.push(m); }
    Ok(mats)
}

fn load_stl(path: &str) -> Result<Model, String> {
    let content = match fs::read(path) {
        Ok(c) => c,
        Err(_) => return Err(format!(
            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed",
            path
        )),
    };
    // Try ASCII first
    if let Ok(s) = std::str::from_utf8(&content) {
        if s.starts_with("solid") && s.contains("facet") {
            return load_stl_ascii(s);
        }
    }
    load_stl_bin(&content)
}

fn load_stl_ascii(content: &str) -> Result<Model, String> {
    let mut mesh = Mesh::default();
    let mut vertices = Vec::new();
    let mut normals = Vec::new();
    let mut current_normal = Vec3::default();
    let mut face_vs: Vec<usize> = Vec::new();
    let mut face_n: Option<usize> = None;

    for line in content.lines() {
        let line = line.trim();
        let mut parts = line.split_whitespace();
        let k = parts.next().unwrap_or("");
        match k {
            "facet" => {
                if parts.next() == Some("normal") {
                    let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                    if nums.len() >= 3 {
                        current_normal = Vec3::new(nums[0], nums[1], nums[2]);
                        normals.push(current_normal);
                        face_n = Some(normals.len() - 1);
                    }
                }
                face_vs.clear();
            }
            "vertex" => {
                let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                if nums.len() >= 3 {
                    vertices.push(Vec3::new(nums[0], nums[1], nums[2]));
                    face_vs.push(vertices.len() - 1);
                }
            }
            "endfacet" => {
                if face_vs.len() >= 3 {
                    let mut face = Face::default();
                    for v in &face_vs { face.vs.push(*v); face.ns.push(face_n); }
                    mesh.faces.push(face);
                }
                face_vs.clear();
            }
            _ => {}
        }
    }
    mesh.vertices = vertices;
    mesh.normals = normals;
    Ok(Model { meshes: vec![mesh] })
}

fn load_stl_bin(content: &[u8]) -> Result<Model, String> {
    // Binary STL: 80-byte header, 4-byte count, then triangles (50 bytes each)
    if content.len() < 84 { return Err("stl too short".into()); }
    let count = u32::from_le_bytes([content[80], content[81], content[82], content[83]]) as usize;
    let mut mesh = Mesh::default();
    let mut offset = 84;
    for _ in 0..count {
        if offset + 50 > content.len() { break; }
        let read_f32 = |off: usize| -> f64 {
            f32::from_le_bytes([content[off], content[off+1], content[off+2], content[off+3]]) as f64
        };
        let n = Vec3::new(read_f32(offset), read_f32(offset+4), read_f32(offset+8));
        mesh.normals.push(n);
        let n_idx = mesh.normals.len() - 1;
        let mut face = Face::default();
        for t in 0..3 {
            let base = offset + 12 + t*12;
            let v = Vec3::new(read_f32(base), read_f32(base+4), read_f32(base+8));
            mesh.vertices.push(v);
            face.vs.push(mesh.vertices.len() - 1);
            face.ns.push(Some(n_idx));
        }
        mesh.faces.push(face);
        offset += 50;
    }
    Ok(Model { meshes: vec![mesh] })
}
