        match key {
            "newmtl" => {
                if let Some(m) = current.take() {
                    mats.push(m);
                }
                current = Some(Material { name: parts.next().unwrap_or("").to_string(), diffuse: (1.0, 1.0, 1.0) });
            }
            "Kd" => {
                let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                if let Some(m) = current.as_mut() {
                    if nums.len() >= 3 {
                        m.diffuse = (nums[0], nums[1], nums[2]);
                    }
                }
            }
            _ => {}
        }
    }
    if let Some(m) = current.take() { mats.push(m); }
    Ok(mats)
}

fn load_stl(path: &str) -> Result<Model, String> {
    let content = match fs::read(path) {
        Ok(c) => c,
        Err(_) => return Err(format!(
            "filename: [{}] couldn't load, tobj couldnt load/parse OBJ. open file failed",
            path
        )),
    };
    // Try ASCII first
    if let Ok(s) = std::str::from_utf8(&content) {
        if s.starts_with("solid") && s.contains("facet") {
            return load_stl_ascii(s);
        }
    }
    load_stl_bin(&content)
}

fn load_stl_ascii(content: &str) -> Result<Model, String> {
    let mut mesh = Mesh::default();
    let mut vertices = Vec::new();
    let mut normals = Vec::new();
    let mut current_normal = Vec3::default();
    let mut face_vs: Vec<usize> = Vec::new();
    let mut face_n: Option<usize> = None;

    for line in content.lines() {
        let line = line.trim();
        let mut parts = line.split_whitespace();
        let k = parts.next().unwrap_or("");
        match k {
            "facet" => {
                if parts.next() == Some("normal") {
                    let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                    if nums.len() >= 3 {
                        current_normal = Vec3::new(nums[0], nums[1], nums[2]);
                        normals.push(current_normal);
                        face_n = Some(normals.len() - 1);
                    }
                }
                face_vs.clear();
            }
            "vertex" => {
                let nums: Vec<f64> = parts.filter_map(|s| s.parse().ok()).collect();
                if nums.len() >= 3 {
                    vertices.push(Vec3::new(nums[0], nums[1], nums[2]));
                    face_vs.push(vertices.len() - 1);
                }
            }
            "endfacet" => {
                if face_vs.len() >= 3 {
                    let mut face = Face::default();
                    for v in &face_vs { face.vs.push(*v); face.ns.push(face_n); }
                    mesh.faces.push(face);
                }
                face_vs.clear();
            }
            _ => {}
        }
    }
    mesh.vertices = vertices;
    mesh.normals = normals;
    Ok(Model { meshes: vec![mesh] })
}

fn load_stl_bin(content: &[u8]) -> Result<Model, String> {
    // Binary STL: 80-byte header, 4-byte count, then triangles (50 bytes each)
    if content.len() < 84 { return Err("stl too short".into()); }
    let count = u32::from_le_bytes([content[80], content[81], content[82], content[83]]) as usize;
    let mut mesh = Mesh::default();
    let mut offset = 84;
    for _ in 0..count {
        if offset + 50 > content.len() { break; }
        let read_f32 = |off: usize| -> f64 {
            f32::from_le_bytes([content[off], content[off+1], content[off+2], content[off+3]]) as f64
        };
        let n = Vec3::new(read_f32(offset), read_f32(offset+4), read_f32(offset+8));
        mesh.normals.push(n);
        let n_idx = mesh.normals.len() - 1;
        let mut face = Face::default();
        for t in 0..3 {
            let base = offset + 12 + t*12;
            let v = Vec3::new(read_f32(base), read_f32(base+4), read_f32(base+8));
            mesh.vertices.push(v);
            face.vs.push(mesh.vertices.len() - 1);
            face.ns.push(Some(n_idx));
        }
        mesh.faces.push(face);
        offset += 50;
    }
    Ok(Model { meshes: vec![mesh] })
}
