// Basic 3D triangle rasterizer with flat shading

use crate::math::{Vec3, rotate};
use crate::obj::{Model, Material};

pub struct Pixel {
    pub ch: char,
    pub fg: (u8, u8, u8),
    pub bg: (u8, u8, u8),
}

pub struct Canvas {
    pub w: usize,
    pub h: usize,
    pub pixels: Vec<Pixel>,
    pub zbuf: Vec<f64>,
}

impl Canvas {
    pub fn new(w: usize, h: usize) -> Self {
        // The image is (w+1) wide internally, with a '\n' at col=w by default.
        let cols = w + 1;
        let total = cols * h;
        let mut pixels = Vec::with_capacity(total);
        let mut zbuf = Vec::with_capacity(total);
        for row in 0..h {
            for col in 0..cols {
                let ch = if col == w { '\n' } else { ' ' };
                pixels.push(Pixel { ch, fg: (0,0,0), bg: (25,25,25) });
                zbuf.push(f64::INFINITY);
            }
        }
        Canvas { w, h, pixels, zbuf }
    }
    pub fn idx(&self, x: usize, y: usize) -> usize { y * (self.w + 1) + x }
}

const SHADES: &[u8] = b" .:-=+*#%@";

pub fn render(models: &[Model], w: usize, h: usize, yaw: f64, pitch: f64, roll: f64) -> Canvas {
    let mut canvas = Canvas::new(w, h);

    // Gather all meshes, apply rotation, and compute bounds.
    let mut all_tris: Vec<(Vec3, Vec3, Vec3, Vec3, Option<Material>)> = Vec::new(); // (v0, v1, v2, normal, mat)
    let mut bbox_min = Vec3::new(f64::INFINITY, f64::INFINITY, f64::INFINITY);
    let mut bbox_max = Vec3::new(f64::NEG_INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY);

    for m in models {
        for mesh in &m.meshes {
            // Transform vertices
            let mut tvs: Vec<Vec3> = mesh.vertices.iter().map(|v| rotate(*v, yaw, pitch, roll)).collect();
            if tvs.is_empty() { tvs = mesh.vertices.clone(); }
            // Transform normals
            let tns: Vec<Vec3> = mesh.normals.iter().map(|n| rotate(*n, yaw, pitch, roll)).collect();

            for face in &mesh.faces {
                if face.vs.len() < 3 { continue; }
                let base_v0 = tvs.get(face.vs[0]).cloned().unwrap_or_default();
                for k in 1..face.vs.len()-1 {
                    let v0 = base_v0;
                    let v1 = tvs.get(face.vs[k]).cloned().unwrap_or_default();
                    let v2 = tvs.get(face.vs[k+1]).cloned().unwrap_or_default();
                    let normal = if !tns.is_empty() {
                        // Average the normals at the face's vertices
                        let n0 = face.ns.get(0).and_then(|x| *x).and_then(|i| tns.get(i).cloned()).unwrap_or_default();
                        n0
                    } else {
                        v1.sub(v0).cross(v2.sub(v0)).normalize()
                    };
                    all_tris.push((v0, v1, v2, normal, mesh.material.clone()));
                    for p in &[v0, v1, v2] {
                        bbox_min.x = bbox_min.x.min(p.x);
                        bbox_min.y = bbox_min.y.min(p.y);
                        bbox_min.z = bbox_min.z.min(p.z);
                        bbox_max.x = bbox_max.x.max(p.x);
                        bbox_max.y = bbox_max.y.max(p.y);
                        bbox_max.z = bbox_max.z.max(p.z);
                    }
                }
            }
        }
    }

    if all_tris.is_empty() { return canvas; }

    // Compute transform to screen space: fit bbox into canvas.
    let center = Vec3::new(
        (bbox_min.x + bbox_max.x) * 0.5,
        (bbox_min.y + bbox_max.y) * 0.5,
        (bbox_min.z + bbox_max.z) * 0.5,
    );
    let size_x = (bbox_max.x - bbox_min.x).max(1e-6);
    let size_y = (bbox_max.y - bbox_min.y).max(1e-6);
    // Fit into 80% of canvas
    let fit_w = w as f64 * 0.8;
    let fit_h = h as f64 * 0.8;
    let scale = (fit_w / size_x).min(fit_h / size_y);
    let cx = w as f64 / 2.0;
    let cy = h as f64 / 2.0;

    // Light direction (fixed)
    let light = Vec3::new(0.0, 0.0, 1.0);

    for (v0, v1, v2, normal, mat) in &all_tris {
        // Project to 2D (orthographic)
        let proj = |v: &Vec3| -> (f64, f64, f64) {
            let px = (v.x - center.x) * scale + cx;
            let py = -(v.y - center.y) * scale + cy;
            let pz = v.z;
            (px, py, pz)
        };
        let (x0,y0,z0) = proj(v0);
        let (x1,y1,z1) = proj(v1);
        let (x2,y2,z2) = proj(v2);

        // Compute shade
        let shade = normal.normalize().dot(light).abs();
        let shade_idx = ((shade * (SHADES.len() as f64)) as usize).min(SHADES.len() - 1);
        let ch = SHADES[shade_idx] as char;

        // Face color
