        let _ = writeln!(out, "let frames = [");
        for f in 0..frames {
            // Rotate per frame based on f
            let per_frame_angle = (2.0 * std::f64::consts::PI) * (f as f64) / (frames as f64);
            let yaw = opts.yaw + per_frame_angle;
            let pitch = opts.pitch;
            let roll = opts.roll;
            let canvas = render(models, opts.width as usize, opts.height as usize, yaw, pitch, roll);
            let _ = write!(out, "`");
            let _ = writeln!(out, "");
            write_webify_pixels(&mut out, &canvas);
            if f + 1 < frames {
                let _ = writeln!(out, " `,");
            } else {
                let _ = write!(out, " `];");
            }
        }
        return;
    }

    // Default: ANSI terminal output (from image subcommand)
    let canvas = render(models, opts.width as usize, opts.height as usize, opts.yaw, opts.pitch, opts.roll);
    write_ansi_pixels(&mut out, &canvas);
}

fn write_ansi_pixels<W: Write>(out: &mut W, canvas: &Canvas) {
    let mut buf = Vec::with_capacity(canvas.pixels.len() * 40);
    for p in &canvas.pixels {
        // Background
        buf.extend_from_slice(b"\x1b[48;2;");
        push_num(&mut buf, p.bg.0); buf.push(b';');
        push_num(&mut buf, p.bg.1); buf.push(b';');
        push_num(&mut buf, p.bg.2);
        buf.push(b'm');
        // Foreground
        buf.extend_from_slice(b"\x1b[38;2;");
        push_num(&mut buf, p.fg.0); buf.push(b';');
        push_num(&mut buf, p.fg.1); buf.push(b';');
        push_num(&mut buf, p.fg.2);
        buf.push(b'm');
        // Char
        buf.push(p.ch as u8);
        // Reset
        buf.extend_from_slice(b"\x1b[49m\x1b[39m");
    }
    let _ = out.write_all(&buf);
}

fn write_webify_pixels<W: Write>(out: &mut W, canvas: &Canvas) {
    let mut buf = Vec::new();
    for p in &canvas.pixels {
        if p.ch == '\n' {
            buf.push(b'\n');
        } else {
            buf.extend_from_slice(b"<span style=\"color:rgb(");
            push_num(&mut buf, p.fg.0); buf.push(b',');
            push_num(&mut buf, p.fg.1); buf.push(b',');
            push_num(&mut buf, p.fg.2);
            buf.extend_from_slice(b")\">");
            buf.push(p.ch as u8);
        }
    }
    let _ = out.write_all(&buf);
}

fn push_num(buf: &mut Vec<u8>, n: u8) {
    let s = n.to_string();
    buf.extend_from_slice(s.as_bytes());
}
