// Basic 3D triangle rasterizer with flat shading

use crate::math::{Vec3, rotate};
use crate::obj::{Model, Material};

pub struct Pixel {
    pub ch: char,
    pub fg: (u8, u8, u8),
    pub bg: (u8, u8, u8),
}

pub struct Canvas {
    pub w: usize,
    pub h: usize,
    pub pixels: Vec<Pixel>,
    pub zbuf: Vec<f64>,
}

impl Canvas {
    pub fn new(w: usize, h: usize) -> Self {
        // Internal width is (w+1). NL at col=w by default acts as row separator.
        let cols = w + 1;
        let total = cols * h;
        let mut pixels = Vec::with_capacity(total);
        let mut zbuf = Vec::with_capacity(total);
        for _row in 0..h {
