                    all_tris.push((v0, v1, v2, normal, mesh.material.clone()));
                    for p in &[v0, v1, v2] {
                        bbox_min.x = bbox_min.x.min(p.x);
                        bbox_min.y = bbox_min.y.min(p.y);
                        bbox_min.z = bbox_min.z.min(p.z);
                        bbox_max.x = bbox_max.x.max(p.x);
                        bbox_max.y = bbox_max.y.max(p.y);
                        bbox_max.z = bbox_max.z.max(p.z);
                    }
                }
            }
        }
    }

    if all_tris.is_empty() { return canvas; }

    let center = Vec3::new(
        (bbox_min.x + bbox_max.x) * 0.5,
        (bbox_min.y + bbox_max.y) * 0.5,
        (bbox_min.z + bbox_max.z) * 0.5,
    );
    let size_x = (bbox_max.x - bbox_min.x).max(1e-6);
    let size_y = (bbox_max.y - bbox_min.y).max(1e-6);
    let fit_w = w as f64 * 0.8;
    let fit_h = h as f64 * 0.8;
    let scale = (fit_w / size_x).min(fit_h / size_y);
    let cx = w as f64 / 2.0;
    let cy = h as f64 / 2.0;

    let light = Vec3::new(0.0, 0.0, 1.0);

    for (v0, v1, v2, normal, mat) in &all_tris {
        let proj = |v: &Vec3| -> (f64, f64, f64) {
            let px = (v.x - center.x) * scale + cx;
            let py = -(v.y - center.y) * scale + cy;
            let pz = v.z;
            (px, py, pz)
        };
        let (x0,y0,z0) = proj(v0);
        let (x1,y1,z1) = proj(v1);
        let (x2,y2,z2) = proj(v2);

        let shade = normal.normalize().dot(light).abs();
        let shade_idx = ((shade * (SHADES.len() as f64)) as usize).min(SHADES.len() - 1);
        let ch = SHADES[shade_idx] as char;

        let (r, g, b) = if let Some(m) = mat {
            let (r, g, b) = m.diffuse;
            ((r * 255.0) as u8, (g * 255.0) as u8, (b * 255.0) as u8)
        } else {
            (255, 255, 255)
        };

        let min_x = x0.min(x1).min(x2).floor().max(0.0) as i32;
        let max_x = x0.max(x1).max(x2).ceil().min(w as f64 - 1.0) as i32;
        let min_y = y0.min(y1).min(y2).floor().max(0.0) as i32;
        let max_y = y0.max(y1).max(y2).ceil().min(h as f64 - 1.0) as i32;

        let area = edge_fn(x0,y0, x1,y1, x2,y2);
        if area.abs() < 1e-12 { continue; }

        for y in min_y..=max_y {
            for x in min_x..=max_x {
                let px = x as f64 + 0.5;
                let py = y as f64 + 0.5;
                let w0 = edge_fn(x1,y1, x2,y2, px,py);
                let w1 = edge_fn(x2,y2, x0,y0, px,py);
                let w2 = edge_fn(x0,y0, x1,y1, px,py);
                let inside = (w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0) || (w0 <= 0.0 && w1 <= 0.0 && w2 <= 0.0);
                if !inside { continue; }
                let w0n = w0 / area;
                let w1n = w1 / area;
                let w2n = w2 / area;
                let z = w0n*z0 + w1n*z1 + w2n*z2;
                let idx = canvas.idx(x as usize, y as usize);
                if z > canvas.zbuf[idx] { continue; }
                canvas.zbuf[idx] = z;
                canvas.pixels[idx] = Pixel { ch, fg: (r,g,b), bg: (25,25,25) };
            }
        }
    }

    canvas
}

fn edge_fn(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64) -> f64 {
    (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
}
